const DATA_RESET_VERSION = '2026-07-15-start-new';

function applyOneTimeDataReset() {
  try {
    if (localStorage.getItem('aims-data-reset-version') === DATA_RESET_VERSION) return;
    Object.keys(localStorage).filter((key) => key.startsWith('aims-')).forEach((key) => localStorage.removeItem(key));
    localStorage.setItem('aims-data-reset-version', DATA_RESET_VERSION);
  } catch {
    // Browser storage may be blocked; database reset still keeps backend data clean.
  }
}

applyOneTimeDataReset();

