 const [search,setSearch]=useState('');const [notice,setNotice]=useState('');const configs=[['Core-SW-01','Cisco IOS XE','Compliant','2 min ago','v24.7'],['FW-Headquarters','FortiOS','Review required','8 min ago','v18.3'],['Edge-Router-NY','Cisco IOS XE','Out of date','35 min ago','v21.1'],['AP-London-04','ArubaOS','Compliant','1 hr ago','v11.8']];const visible=configs.filter(row=>row.join(' ').toLowerCase().includes(search.toLowerCase()));
