function loadStoredRoomComponents(): StoredRoomComponent[] {
 return [];
}
async function ensureRoomComponentsToken(force=false) {
 const saved=localStorage.getItem('aims-api-token');
 if(saved&&!force)return saved;
 const response=await fetch(`${ROOM_COMPONENTS_MENU_API}/auth/login`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:'',password:''})});
 const json=await response.json();
 if(!response.ok||!json.data?.token)throw new Error(json.message||'Unable to authenticate to the API.');
 localStorage.setItem('aims-api-token',json.data.token);
 return json.data.token as string;
}
async function loadStoredRoomComponentsFromBackend(): Promise<StoredRoomComponent[]> {
 let token=await ensureRoomComponentsToken();
 const load=async(auth:string):Promise<StoredRoomComponent[]>=>{
  const response=await fetch(`${ROOM_COMPONENTS_MENU_API}/infrastructure/Components`,{headers:{Authorization:`Bearer ${auth}`}});
  if(response.status===401){localStorage.removeItem('aims-api-token');token=await ensureRoomComponentsToken(true);return load(token)}
  const json=await response.json();
  if(response.status===404)return [];
  if(!response.ok)throw new Error(json.detail||json.message||'Unable to load components from database.');
  const rows=Array.isArray(json.data?.records)?json.data.records:[];
  const clean=rows.filter((row:unknown):row is StoredRoomComponent=>Boolean(row&&typeof row==='object'&&typeof (row as StoredRoomComponent).id==='string'));
  return clean;
 };
 return load(token);
}
async function saveStoredRoomComponentsToBackend(rows: StoredRoomComponent[]) {
 let token=await ensureRoomComponentsToken();
 const save=async(auth:string):Promise<void>=>{
  const response=await fetch(`${ROOM_COMPONENTS_MENU_API}/infrastructure/Components`,{method:'PUT',headers:{Authorization:`Bearer ${auth}`,'Content-Type':'application/json'},body:JSON.stringify({records:rows.map(row=>({...row,_merge_key:`component:${row.roomKey||''}:${row.id||row.name||''}`.toLowerCase()}))})});
  if(response.status===401){localStorage.removeItem('aims-api-token');token=await ensureRoomComponentsToken(true);return save(token)}
  const json=await response.json();
  if(!response.ok)throw new Error(json.detail||json.message||'Unable to save component to database.');
 };
 await save(token);
 window.dispatchEvent(new CustomEvent('aims:room-components-changed'));
}
async function loadDeviceStatusRefreshSeconds() {
 let token=await ensureRoomComponentsToken();
 const load=async(auth:string):Promise<number>=>{
  const response=await fetch(`${ROOM_COMPONENTS_MENU_API}/settings/device_status_refresh_seconds`,{headers:{Authorization:`Bearer ${auth}`}});
  if(response.status===401){localStorage.removeItem('aims-api-token');token=await ensureRoomComponentsToken(true);return load(token)}
  const json=await response.json();
  if(!response.ok)throw new Error(json.detail||json.message||'Unable to load component refresh setting.');
  const seconds=Number(json.data?.value||60);
  return Number.isFinite(seconds)?Math.max(15,Math.min(3600,Math.round(seconds))):60;
 };
 return load(token);
}
async function testStoredRoomComponent(component:StoredRoomComponent) {
 let token=await ensureRoomComponentsToken();
 const test=async(auth:string):Promise<ComponentTestResult>=>{
  const response=await fetch(`${ROOM_COMPONENTS_MENU_API}/infrastructure/Components/test`,{method:'POST',headers:{Authorization:`Bearer ${auth}`,'Content-Type':'application/json'},body:JSON.stringify({component})});
  if(response.status===401){localStorage.removeItem('aims-api-token');token=await ensureRoomComponentsToken(true);return test(token)}
  const json=await response.json();
  if(!response.ok)throw new Error(json.detail||json.message||'Component test failed.');
  return json.data as ComponentTestResult;
 };
 return test(token);
}
function componentWithRefreshError(component:StoredRoomComponent,error:unknown):StoredRoomComponent {
 const now=new Date().toISOString();
 return {
  ...component,
  status:'Warning',
  specs:{...(component.specs||{}),lastTestAt:now,lastTestError:error instanceof Error?error.message:'Component refresh failed.'},
  updatedAt:now,
 };
}
async function refreshMonitoredComponentsFromConfig() {
 const rows=await loadStoredRoomComponentsFromBackend();
 const monitored=rows.filter(component=>component.monitoringEnabled);
 if(!monitored.length)return;
 const updates=new globalThis.Map<string,StoredRoomComponent>();
 for(const component of monitored){
  try{
   const result=await testStoredRoomComponent(component);
   updates.set(component.id,componentWithTestResult(component,result));
  }catch(error){
   updates.set(component.id,componentWithRefreshError(component,error));
  }
 }
 if(!updates.size)return;
 await saveStoredRoomComponentsToBackend(rows.map(component=>updates.get(component.id)||component));
 localStorage.setItem('aims-components-last-refresh',new Date().toISOString());
}
function AutoComponentRefreshService() {
 const running=useRef(false);
 useEffect(()=>{
  let stopped=false;
  let timer=0;
  const schedule=async()=>{
   let seconds=60;
   try{seconds=await loadDeviceStatusRefreshSeconds()}catch{seconds=60}
   if(stopped)return;
   timer=window.setTimeout(tick,seconds*1000);
  };
  const tick=async()=>{
   if(stopped)return;
   if(!document.hidden&&!running.current){
    running.current=true;
    try{await refreshMonitoredComponentsFromConfig()}catch{undefined}finally{running.current=false}
   }
   if(!stopped)void schedule();
  };
  const reset=()=>{if(timer)window.clearTimeout(timer);void tick()};
  window.addEventListener('aims:status-refresh-config-changed',reset);
  void tick();
  return()=>{stopped=true;if(timer)window.clearTimeout(timer);window.removeEventListener('aims:status-refresh-config-changed',reset)};
 },[]);
 return null;
}
